package dev.horizonlab.parity;
import com.google.gson.*;import com.mojang.serialization.Codec;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
import net.minecraft.core.*;import net.minecraft.core.component.*;import net.minecraft.world.item.*;
/** Native item-stack copy/count/component kernels, retaining canonical EMPTY identity. */
public final class VanillaItemStackStorageOracle {
    static final class Stop extends RuntimeException {}
    static DataComponentType<Integer>[] keys;static Item[] items;static Field components,count,item,patchMap;static Object removed,unsafe;static Method allocate;
    static Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
    static <T>T make(Class<T> c)throws Exception{return c.cast(allocate.invoke(unsafe,c));}
    static String optional(Object v){return v==null||v==removed?"none":v.toString();}
    static int kind(Item i){for(int k=0;k<items.length;k++)if(items[k]==i)return k;throw new AssertionError();}
    static int key(Object k){for(int i=0;i<keys.length;i++)if(keys[i]==k)return i;throw new AssertionError();}
    static DataComponentMap prototype(JsonArray a){var b=DataComponentMap.builder();for(var e:a){var p=e.getAsJsonArray();b.set(keys[p.get(0).getAsInt()],p.get(1).getAsInt());}return b.build();}
    static DataComponentPatch patch(JsonArray a){var b=DataComponentPatch.builder();for(var e:a){var p=e.getAsJsonArray();int k=p.get(0).getAsInt();if(p.get(1).isJsonNull())b.remove(keys[k]);else b.set(keys[k],p.get(1).getAsInt());}return b.build();}
    static String patchText(DataComponentPatch p)throws Exception{var join=new StringJoiner(",");for(var e:((Map<?,?>)patchMap.get(p)).entrySet())join.add(key(e.getKey())+"="+optional(e.getValue()));return join.toString();}
    static String snapshot(ItemStack s){try{var raw=(PatchedDataComponentMap)components.get(s);var h=(Holder<?>)item.get(s);var visible=new StringJoiner(",");for(var k:keys)visible.add(optional(s.get(k)));var entries=new StringJoiner(",");for(var e:raw)entries.add(key(e.type())+"="+e.value());return (s==ItemStack.EMPTY)+" "+(h==null?-1:kind((Item)h.value()))+" "+kind(s.getItem())+" "+count.getInt(s)+" "+s.getCount()+" "+s.getPopTime()+" "+s.isEmpty()+" | "+visible+" | "+entries+" | "+patchText(raw.asPatch())+" | "+patchText(s.getComponentsPatch());}catch(Exception e){throw new AssertionError(e);}}
    static void all(PrintWriter out,ItemStack[] slots){for(int i=0;i<slots.length;i++)out.println("slot "+i+" "+snapshot(slots[i]));for(int a=0;a<3;a++)for(int b=a+1;b<3;b++)out.println("equal "+a+" "+b+" "+(slots[a]==slots[b])+" "+ItemStack.isSameItem(slots[a],slots[b])+" "+ItemStack.isSameItemSameComponents(slots[a],slots[b])+" "+ItemStack.matches(slots[a],slots[b]));}
    static final class Data{PrintWriter out;JsonObject op;ItemStack target;int calls;void event(){out.println("infinite | "+snapshot(target));calls++;if(op.get("fail").getAsBoolean())throw new Stop();if(op.get("mutate").getAsBoolean()){target.setCount(op.get("after_count").getAsInt());target.setPopTime(op.get("after_pop").getAsInt());for(var e:op.getAsJsonArray("after_components")){var pair=e.getAsJsonArray();target.set(keys[pair.get(0).getAsInt()],pair.get(1).isJsonNull()?null:pair.get(1).getAsInt());}}}}
    static final class Actor extends net.minecraft.world.entity.decoration.ArmorStand{Data d;Actor(){super(null,null);}@Override public boolean hasInfiniteMaterials(){d.event();return d.op.get("infinite").getAsBoolean();}}
    @SuppressWarnings("unchecked")public static void main(String[] args)throws Exception{net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();keys=new DataComponentType[4];for(int i=0;i<keys.length;i++)keys[i]=DataComponentType.<Integer>builder().persistent(Codec.INT).build();items=new Item[]{Items.AIR,Items.STICK,Items.SHIELD};components=field(ItemStack.class,"components");count=field(ItemStack.class,"count");item=field(ItemStack.class,"item");patchMap=field(DataComponentPatch.class,"map");removed=field(Class.forName("net.minecraft.core.component.Removed"),"INSTANCE").get(null);var u=Class.forName("sun.misc.Unsafe");unsafe=field(u,"theUnsafe").get(null);allocate=u.getMethod("allocateInstance",Class.class);Path dir=Path.of(args[1]);try(var out=new PrintWriter(Files.newBufferedWriter(dir.resolve(args[0]+".txt")));var lines=Files.lines(dir.resolve("inputs.txt"))){for(var line:(Iterable<String>)lines::iterator){var f=JsonParser.parseString(line).getAsJsonObject();for(int i=0;i<3;i++)items[i].builtInRegistryHolder().bindComponents(prototype(f.getAsJsonArray("prototypes").get(i).getAsJsonArray()));ItemStack.EMPTY.setCount(0);ItemStack.EMPTY.setPopTime(0);((PatchedDataComponentMap)components.get(ItemStack.EMPTY)).clearPatch();var slots=new ItemStack[3];for(int i=0;i<3;i++){var v=f.getAsJsonArray("stacks").get(i).getAsJsonObject();int type=v.get("item").getAsInt();slots[i]=type<0?ItemStack.EMPTY:new ItemStack(items[type],v.get("count").getAsInt());if(type>=0){slots[i].setPopTime(v.get("pop").getAsInt());((PatchedDataComponentMap)components.get(slots[i])).restorePatch(patch(v.getAsJsonArray("patch")));}}var d=new Data();d.out=out;var actor=make(Actor.class);actor.d=d;all(out,slots);for(var ov:f.getAsJsonArray("ops")){var op=ov.getAsJsonObject();d.op=op;d.calls=0;int a=op.get("a").getAsInt(),b=op.get("b").getAsInt(),amount=op.get("amount").getAsInt();d.target=slots[a];try{switch(op.get("kind").getAsString()){
        case "count":slots[a].setCount(amount);break;case "pop":slots[a].setPopTime(amount);break;case "grow":slots[a].grow(amount);break;case "shrink":slots[a].shrink(amount);break;case "limit":slots[a].limitSize(amount);break;
        case "set":out.println("old "+optional(slots[a].set(keys[op.get("key").getAsInt()],op.get("value").isJsonNull()?null:op.get("value").getAsInt())));break;
        case "copy":slots[b]=slots[a].copy();break;case "copy-count":slots[b]=slots[a].copyWithCount(amount);break;case "copy-clear":slots[b]=slots[a].copyAndClear();break;case "split":slots[b]=slots[a].split(amount);break;
        case "transmute":slots[b]=slots[a].transmuteCopy(items[op.get("item").getAsInt()],amount);break;
        case "consume":slots[a].consume(amount,op.get("actor").getAsBoolean()?actor:null);break;
        case "consume-return":slots[b]=slots[a].consumeAndReturn(amount,op.get("actor").getAsBoolean()?actor:null);break;
        default:throw new AssertionError();}out.println("result ok "+d.calls);}catch(Stop|NullPointerException e){out.println("result error "+d.calls);}all(out,slots);}}}}
}
